(135,0,'2026-07-05 20:44:25','2026-07-05 23:44:25','\n.ywcps-wrapper { position: relative; }\n.ywcps-wrapper .ywcps-nav, .ywcps-wrapper .ywcps-nav-prev, .ywcps-wrapper .ywcps-nav-next { display: none !important; }\n.ywcps-wrapper .owl-nav { display: flex !important; justify-content: space-between; position: absolute; top: 40%; left: 0; right: 0; padding: 0 14px; pointer-events: none; margin: 0 !important; box-sizing: border-box; }\n.ywcps-wrapper .owl-nav .owl-prev, .ywcps-wrapper .owl-nav .owl-next {\n  pointer-events: all;\n  font-size: 0 !important;\n  width: 42px; height: 42px;\n  border-radius: 50%;\n  background: #C8721A !important;\n  color: #FDFAF5 !important;\n  display: flex; align-items: center; justify-content: center;\n  box-shadow: 0 2px 6px rgba(0,0,0,0.25);\n  transition: background 0.2s ease;\n  margin: 0 !important;\n}\n.ywcps-wrapper .owl-nav .owl-prev:hover, .ywcps-wrapper .owl-nav .owl-next:hover { background: #2C1A06 !important; }\n.ywcps-wrapper .owl-nav .owl-prev:before { content: \"\\2039\"; font-size: 26px !important; line-height: 1; }\n.ywcps-wrapper .owl-nav .owl-next:after { content: \"\\203A\"; font-size: 26px !important; line-height: 1; }\n.ywcps-wrapper .owl-dots { text-align: center; margin-top: 15px; }\n.ywcps-wrapper .owl-dots .owl-dot span { background: #E4D9C7 !important; }\n.ywcps-wrapper .owl-dots .owl-dot.active span { background: #C8721A !important; }\n\n\n/* Categoria: 2 icones por linha no mobile, icones menores */\n@media (max-width: 767px) {\n  .elementor-element-cac0e2a .elementor-container { flex-wrap: wrap !important; }\n  .elementor-element-cac0e2a > .elementor-container > .elementor-column {\n    width: 50% !important;\n    max-width: 50% !important;\n    flex: 0 0 50% !important;\n  }\n  .elementor-element-cac0e2a .elementor-image-box-img { width: 60px !important; }\n  .elementor-element-cac0e2a .elementor-image-box-img img { width: 60px !important; height: 60px !important; }\n  .elementor-element-cac0e2a .elementor-image-box-content { margin-top: 8px !important; }\n  .elementor-element-cac0e2a .elementor-image-box-title { font-size: 14px !important; }\n}\n','astra-child','','publish','closed','closed','','astra-child','','','2026-07-06 19:26:19','2026-07-06 22:26:19','',0,'http://localhost:8080/astra-child/',0,'custom_css','',0),
